// THE DEFERRED CONVERGENCE (#1374). `converge-item.mjs` performs the terminal
// transition over REST, and `invoke.mjs` hands work to Claude Code WEB sessions,
// whose shell has no usable REST credential and no `GITHUB_REPOSITORY`. So the one
// step at the end of every agentic run is the one step that environment cannot
// take, and a run that did its job correctly parks looking failed.
//
// THE SPLIT IS UNCHANGED — the session still supplies only the judgment. What
// moves is WHERE the transition executes: the session lodges a REQUEST naming the
// outcome it chose, and the next Actions-side pass, which holds a real token,
// performs the five side effects on its behalf. The session never performs them.
// Handing the session the side effects instead is the hand-performed transition
// `converge-item.mjs`'s own header exists to prevent.
//
// THE PAYLOAD IS OPAQUE, and deliberately: `summary` is free prose written by a
// model, so it may carry backticks, fences, `-->`, anything. Base64 of JSON inside
// an HTML comment is the only encoding here that a summary cannot break out of —
// standard base64's alphabet has no `-`, so the payload can never close the comment
// early. The human-readable account rides above the marker in plain text; this line
// is for the machine alone.
//
// A REQUEST NAMES THE ITEM IT IS FOR. A comment is copyable and a session is
// untrusted about which item it holds, so the issue number travels INSIDE the
// signed-off payload and the applier refuses a mismatch. Who may lodge one is not
// this module's business — it decodes and validates shape only; the caller
// establishes that the commenter has push access.

import { OUTCOMES } from './converge-item.mjs';

export const REQUEST_MARKER = 'claudinite-converge-request';
export const REQUEST_VERSION = 'v1';

// Standard base64 only (no `-`/`_`), so the encoded payload cannot contain `--`
// and close the HTML comment it rides in.
const MARKER_RE = new RegExp(`<!-- ${REQUEST_MARKER} ${REQUEST_VERSION} ([A-Za-z0-9+/=]+) -->`, 'g');

// The comment a blocked session posts. The prose is what a person reads on the
// item; the marker line is what the applier reads. Both say the same thing, and
// only one of them is authoritative.
export function renderRequest({ issue, outcome, summary, pr = null, nonce = null }) {
  const payload = { issue, outcome, summary, pr: pr ?? null, nonce: nonce ?? null };
  const encoded = Buffer.from(JSON.stringify(payload), 'utf8').toString('base64');
  const spec = OUTCOMES[outcome];
  return `This session could not reach the GitHub REST API to converge this item, so it is `
    + `lodging the convergence it chose. The next scheduler run performs it.\n\n`
    + `- outcome: \`${outcome}\` (${spec?.closes ? 'closes this item' : 'parks it for a person'})\n`
    + (pr ? `- pull request: #${pr}\n` : '')
    + `\n${summary.trim()}\n\n`
    + `<!-- ${REQUEST_MARKER} ${REQUEST_VERSION} ${encoded} -->`;
}

// The payload a comment carries, or null. Every field is validated here rather
// than at the call site: this is the trust boundary between a comment anybody can
// write and a call that closes an issue.
export function parseRequest(body) {
  const text = String(body ?? '');
  MARKER_RE.lastIndex = 0;
  // The LAST marker in one comment wins, for the same reason the last request on
  // an item does: a body assembled by hand can only ever append.
  let encoded = null;
  for (const m of text.matchAll(MARKER_RE)) encoded = m[1];
  if (!encoded) return null;

  let payload = null;
  try { payload = JSON.parse(Buffer.from(encoded, 'base64').toString('utf8')); } catch { return null; }
  if (!payload || typeof payload !== 'object') return null;

  const { issue, outcome, summary, pr, nonce } = payload;
  if (!Number.isInteger(issue) || issue <= 0) return null;
  if (!Object.hasOwn(OUTCOMES, outcome)) return null;
  if (typeof summary !== 'string' || !summary.trim()) return null;
  if (pr != null && (!Number.isInteger(pr) || pr <= 0)) return null;
  // The same bound `converge-item.mjs`'s own parseArgs enforces: a park nobody can
  // act on is not a park, and the applier must not be able to write one either.
  if (outcome === 'approval' && pr == null) return null;
  if (nonce != null && typeof nonce !== 'string') return null;
  return { issue, outcome, summary, pr: pr ?? null, nonce: nonce ?? null };
}

// The request an item is standing on: the NEWEST valid one from an authorized
// commenter, and only if it names this item. A session that lodged twice — a
// correction, a retry — meant the second one.
//
// `mayLodge(comment)` is the caller's authorization test. Answering it needs the
// network, which is why it is injected rather than done here.
export function latestRequest(issue, comments = [], { mayLodge = () => true } = {}) {
  let best = null;
  for (const c of comments) {
    if (!mayLodge(c)) continue;
    const req = parseRequest(c.body);
    // A request naming a DIFFERENT item is not this item's to act on, however it
    // got here — a copied comment, a session that mistook which item it held.
    if (!req || req.issue !== issue) continue;
    const at = new Date(c.created_at ?? 0).getTime();
    if (!Number.isFinite(at) || at <= 0) continue;
    if (!best || at >= best.at) best = { at, request: req, comment: c };
  }
  return best ? best.request : null;
}

