// A read that does not answer is a NO. The failure this refuses is closing an
// issue on a stranger's say-so; the failure it causes is a convergence waiting one
// more scheduler period, which the mechanism already tolerates by design.
export function makePushAccessTest(gh, repo) {
  const cache = new Map();
  return async (login) => {
    if (!login) return false;
    if (cache.has(login)) return cache.get(login);
    const { status, json } = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
    const ok = status === 200 && ['admin', 'write', 'maintain'].includes(json?.permission);
    cache.set(login, ok);
    return ok;
  };
}

