// permission test needs the network and `latestRequest` is pure: collect the
// authors who lodged something parseable here, ask about each once, then let the
// pure selector pick the newest from the authorized set.
export async function requestOn(api, gh, repo, item, { hasPushAccess }) {
  const comments = await api.listComments(gh, repo, item.number);
  const authors = new Set();
  for (const c of comments) if (parseRequest(c.body)) authors.add(c.user?.login ?? null);
  if (!authors.size) return null;

  const allowed = new Set();
  for (const login of authors) if (await hasPushAccess(login)) allowed.add(login);
  if (!allowed.size) return null;

