    try {
      const res = await convergeItem(api, gh, repo, request);
      if (!res.ok) { log(`! #${item.number} lodged a convergence that will not apply: ${res.error}`); continue; }
      log(`- converged #${item.number} on its session's behalf: ${request.outcome}`
        + (res.closed ? ', closed' : ', parked for a person'));
      applied.push({ issue: item.number, outcome: request.outcome, closed: res.closed });
    } catch (e) {
      log(`! converging #${item.number} on its session's behalf failed: ${e.message}`);
    }
  }
