// fourteen live items in the `missingbulb/WIP` member: a web session does its task,
// cannot reach REST to converge, and the item parks looking failed. Two halves —
// the session lodging a request it cannot perform, and the Actions-side pass
// performing it — plus the trust boundary between them.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  renderRequest, parseRequest, latestRequest, requestOn, applyDeferredConvergences,
  makePushAccessTest,
} from '../../queue/converge-request.mjs';
import { canReachRepo } from '../../queue/converge-item.mjs';

const item = (over = {}) => ({
  number: 7, title: '[claudinite-work] p/a', state: 'open', labels: ['task:agent'],
  body: 'packs/p/tasks/a/task.md\n', ...over,
});

const said = (login, body, at = '2026-08-25T05:00:00Z') =>
  ({ user: { login }, body, created_at: at });

// A fake repo whose comment list READS as well as writes, which is what the
// applier needs and the converge fixtures next door do not.
function fakeRepo(issues, { comments = [], permissions = {} } = {}) {
  const state = { issues, comments: [...comments], posted: [] };
  const find = (n) => state.issues.find((i) => i.number === n);
  const gh = async (path, { method = 'GET', body } = {}) => {
    let m;
    if ((m = /^\/repos\/[^/]+\/[^/]+\/collaborators\/([^/]+)\/permission$/.exec(path))) {
      const perm = permissions[decodeURIComponent(m[1])];
      return perm ? { status: 200, json: { permission: perm } } : { status: 404, json: null };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
      if (method === 'POST') { state.posted.push({ issue: Number(m[1]), body: body.body }); return { status: 201, json: {} }; }
      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1);
      return { status: 200, json: page === 1 ? state.comments.filter((c) => (c.issue ?? Number(m[1])) === Number(m[1])) : [] };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
      const i = find(Number(m[1]));
      i.labels = i.labels.filter((l) => l !== decodeURIComponent(m[2]));
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
      find(Number(m[1])).labels.push(...body.labels);
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
      const i = find(Number(m[1]));
      if (method === 'PATCH') Object.assign(i, body);
      return { status: 200, json: i };
    }
    if (/^\/repos\/[^/]+\/[^/]+$/.test(path)) return { status: 200, json: { full_name: 'o/r' } };
    if (/^\/repos\/[^/]+\/[^/]+\/issues\?/.test(path)) return { status: 200, json: [] };
    return { status: 404, json: null };
  };
  return { state, gh, api: { ...require_api(), listComments: async (_g, _r, n) => state.comments.filter((c) => (c.issue ?? n) === n) } };
}

