// THE DEFERRED CONVERGENCES (#1374), before anything is planned against this
// listing. A session `invoke.mjs` handed work to cannot reach REST to converge
// itself, so it lodges the transition and THIS run — which holds a real token —
// performs it. Done here rather than at the end so the closures land in `items`
// below: a dependent freed by one of them is readied in the same run instead of
// waiting for the next.
const { applyDeferredConvergences } = await import('./converge-request.mjs');
